function validate([root]) {
  if (!Array.isArray(root) || root.length < 2) return 'The tree has at least 2 nodes.';
  if (root.some(v => v !== null && (!Number.isInteger(v) || v < 0 || v > 100000))) return 'Node values are whole numbers from 0 to 10^5.';
  if (root[0] === null) return 'A non-empty tree starts with the root value.';
  if (root[root.length - 1] === null) return 'Drop the trailing nulls from the level order.';
  // Each node keeps the open interval its subtree must stay inside.
  const nodes = [{ val: root[0], low: -1, high: 100001 }];
  let index = 1;
  for (let head = 0; index < root.length; head++) {
    if (head >= nodes.length) return 'The level order has values that have no parent node.';
    const node = nodes[head];
    const left = root[index];
    const right = index + 1 < root.length ? root[index + 1] : null;
    if (left !== null) {
      if (left <= node.low || left >= node.val) return 'This must be a binary search tree: smaller values on the left, larger on the right, all distinct.';
      nodes.push({ val: left, low: node.low, high: node.val });
    }
    if (right !== null) {
      if (right <= node.val || right >= node.high) return 'This must be a binary search tree: smaller values on the left, larger on the right, all distinct.';
      nodes.push({ val: right, low: node.val, high: node.high });
    }
    index += 2;
  }
  if (nodes.length < 2) return 'The tree has at least 2 nodes.';
  if (nodes.length > 10000) return 'The tree has at most 10^4 nodes.';
  return null;
}

